import json

def run(_context):
    import adsk.cam, adsk.fusion, adsk.core

    app = adsk.core.Application.get()
    # Get the active document (electronics is separate from design)
    doc = app.activeDocument
    print(f"Active doc: {doc.name}, type: {type(doc).__name__}")

    # Get the design product
    products = doc.products
    cam_product = None
    design_product = None
    for i in range(products.count):
        p = products.item(i)
        print(f"Product {i}: {type(p).__name__}")
        if isinstance(p, adsk.cam.CAM):
            cam_product = p
        if isinstance(p, adsk.fusion.Design):
            design_product = p

    if design_product:
        body = design_product.rootComponent.bRepBodies[0]
        print(f"Body: {body.name}, faces: {body.faces.count}")

        # Find cylinder faces by index
        hole_cylinder_indices = [10, 14, 18, 22, 26, 30, 34]

        # Get faces
        for fi in hole_cylinder_indices[:2]:
            face = body.faces.item(fi)
            geom = face.geometry
            r_mm = geom.radius * 10
            print(f"Face {fi}: type={type(geom).__name__}, r={r_mm:.4f}mm, dia={r_mm*2:.4f}mm")

    if cam_product:
        # Find the drill op
        for s in cam_product.setups:
            if s.name == 'TestSetup':
                for op in s.allOperations:
                    if op.name == '6-Spot_Drill':
                        print(f"\nDrill op: {op.name}")
                        params = op.parameters
                        print(f"Params count: {params.count}")
                        for i in range(min(params.count, 20)):
                            p = params.item(i)
                            if 'hole' in p.name.lower():
                                print(f"  {p.name}: {p.expression}")

