    # Let me try using sketch points for hole locations instead of face selection
    app = adsk.core.Application.get()
    doc = app.activeDocument
    products = doc.products
    design_product = None
    cam_product = None
    for i in range(products.count):
        p = products.item(i)
        if isinstance(p, adsk.fusion.Design):
            design_product = p
        if isinstance(p, adsk.cam.CAM):
            cam_product = p

    # Get TestSetup's WCS to understand coordinate mapping
    for s in cam_product.setups:
        if s.name == 'TestSetup':
            setup = s
            break

    wcs = setup.wcsPoint
    print(f"WCS point type: {type(wcs).__name__}")
    print(f"WCS point: {wcs}")

    # Get WCS orientation
    try:
        wcs_matrix = setup.transform
        print(f"Setup transform: {wcs_matrix}")
    except:
        pass

    try:
        params = setup.parameters
        for i in range(params.count):
            p = params.item(i)
            if 'wcs' in p.name.lower() or 'origin' in p.name.lower() or 'stock' in p.name.lower():
                print(f"  Setup param: {p.name} = {p.expression}")
    except Exception as e:
        print(f"Setup params error: {e}")

